<#
.SYNOPSIS
Imports the developer-downloaded Zoom Plugin SDK for Windows into the RedXe tree so zoom.action.dll builds against
the real IPC proxy (x64 only).

.DESCRIPTION
The SDK is distributed by Zoom from the App Marketplace under the Zoom SDK license and is never committed. Download
zoom-plugin-sdk-windows-<version>.zip, extract it, and run:

    .\ThirdParty\ZoomPluginSdk\Import-ZoomSdk.ps1 -PackageRoot C:\Downloads\zoom-plugin-sdk-windows-7.1.0.2020

The script verifies the layout Zoom documents (<arch>\export_h, <arch>\lib\zToolSuiteIPCProxy.lib,
<arch>\bin\zToolSuiteIPCProxy.dll), copies the x64 headers, import library, and runtime under this directory, and
writes ZoomSdk.props, which Zoom.vcxproj imports when present: it defines ZOOM_PLUGIN_SDK_AVAILABLE, adds export_h to
the includes, links the import library delay-loaded, and copies the bin runtime to <Plugins>\ZoomSdk\ after the
build (never beside RedXe.exe: the package carries its own CRT copies that must not shadow the process runtime).

Plugins\Actions\Zoom\ZoomSdkSession.cpp is pinned against this package version (7.1.0.2020); importing another
version needs -Force and a review of that adapter against the new export_h.

.PARAMETER PackageRoot
The extracted package directory (the one containing x64\ and x86\).

.PARAMETER ExpectedVersion
The version the repository pins; the script refuses another package unless -Force is given.
#>
[CmdletBinding()]
param(
    [Parameter(Mandatory = $true)] [string] $PackageRoot,
    [string] $ExpectedVersion = '7.1.0.2020',
    [switch] $Force
)

$ErrorActionPreference = 'Stop'
$here = Split-Path -Parent $MyInvocation.MyCommand.Path
$source = Join-Path $PackageRoot 'x64'
foreach ($required in @('export_h', 'lib\zToolSuiteIPCProxy.lib', 'bin\zToolSuiteIPCProxy.dll')) {
    if (-not (Test-Path (Join-Path $source $required))) {
        throw "The package at '$PackageRoot' has no x64\$required; expected the Zoom Plugin SDK for Windows layout."
    }
}
$leaf = Split-Path -Leaf $PackageRoot
if (-not $Force -and $leaf -notlike "*$ExpectedVersion*") {
    throw "The package directory '$leaf' does not name the pinned version $ExpectedVersion; pass -Force to import it anyway."
}

$target = Join-Path $here 'x64'
if (Test-Path $target) { Remove-Item -Recurse -Force $target }
New-Item -ItemType Directory -Force (Join-Path $target 'export_h') | Out-Null
New-Item -ItemType Directory -Force (Join-Path $target 'lib') | Out-Null
New-Item -ItemType Directory -Force (Join-Path $target 'bin') | Out-Null
Copy-Item -Recurse -Force (Join-Path $source 'export_h\*') (Join-Path $target 'export_h')
Copy-Item -Force (Join-Path $source 'lib\zToolSuiteIPCProxy.lib') (Join-Path $target 'lib')
Copy-Item -Recurse -Force (Join-Path $source 'bin\*') (Join-Path $target 'bin') -Exclude '*.7z'

$props = @"
<?xml version="1.0" encoding="utf-8"?>
<!-- Generated by Import-ZoomSdk.ps1 from $leaf; not committed. -->
<Project xmlns="http://schemas.microsoft.com/developer/msbuild/2003">
  <PropertyGroup>
    <ZoomSdkRoot>`$(MSBuildThisFileDirectory)x64\</ZoomSdkRoot>
  </PropertyGroup>
  <ItemDefinitionGroup>
    <ClCompile>
      <PreprocessorDefinitions>ZOOM_PLUGIN_SDK_AVAILABLE;WIN32;%(PreprocessorDefinitions)</PreprocessorDefinitions>
      <AdditionalIncludeDirectories>`$(ZoomSdkRoot)export_h;%(AdditionalIncludeDirectories)</AdditionalIncludeDirectories>
    </ClCompile>
    <Link>
      <AdditionalLibraryDirectories>`$(ZoomSdkRoot)lib;%(AdditionalLibraryDirectories)</AdditionalLibraryDirectories>
      <AdditionalDependencies>zToolSuiteIPCProxy.lib;delayimp.lib;%(AdditionalDependencies)</AdditionalDependencies>
      <DelayLoadDLLs>zToolSuiteIPCProxy.dll;%(DelayLoadDLLs)</DelayLoadDLLs>
    </Link>
  </ItemDefinitionGroup>
  <Target Name="CopyZoomSdkRuntime" AfterTargets="Build">
    <ItemGroup>
      <ZoomSdkRuntime Include="`$(ZoomSdkRoot)bin\**\*" Exclude="`$(ZoomSdkRoot)bin\**\*.7z" />
    </ItemGroup>
    <Copy SourceFiles="@(ZoomSdkRuntime)" DestinationFolder="`$(OutDir)ZoomSdk\%(RecursiveDir)" SkipUnchangedFiles="true" />
  </Target>
</Project>
"@
Set-Content -Path (Join-Path $here 'ZoomSdk.props') -Value $props -Encoding UTF8
Write-Host "Imported the Zoom Plugin SDK ($leaf) for x64; rebuild to link zoom.action.dll against it."
